<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Expense; use Illuminate\Http\Request;
class ExpenseController extends Controller { public function index(){return Expense::latest('expense_date')->paginate(50);} public function store(Request $r){$d=$r->validate(['expense_date'=>'required|date','category'=>'required','description'=>'required','amount'=>'required|numeric','payment_mode'=>'required','payee'=>'nullable','reference'=>'nullable','is_capital'=>'boolean']); $d['voucher_no']='V-'.str_pad((string)(Expense::max('id')+1),5,'0',STR_PAD_LEFT); return Expense::create($d);} public function show(Expense $expense){return $expense;} public function update(Request $r,Expense $expense){$expense->update($r->all()); return $expense;} public function destroy(Expense $expense){$expense->delete(); return response()->noContent();} }
